

create database p11;

use p11;


CREATE TABLE `admin` (
  `name` text,
  `pass` text
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


CREATE TABLE `blocked_user` (
  `id` int(11) NOT NULL auto_increment,
  `user` text,
  `tname` text,
  `ip` text,
  `dt` text,
  PRIMARY KEY  (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


CREATE TABLE `bnb_users` (
  `user` text,
  `number` text
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


CREATE TABLE `recommend` (
  `id` int(11) NOT NULL auto_increment,
  `recommendfrom` varchar(45) default NULL,
  `recommendto` varchar(45) default NULL,
  `tname` varchar(45) default NULL,
  `date` text,
  PRIMARY KEY  (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


CREATE TABLE `topics` (
  `id` int(11) NOT NULL auto_increment,
  `name` text,
  `url` text,
  `descr` text,
  `uses` text,
  `image` longblob,
  `auth` text,
  `year` text,
  `rank` int(11) default NULL,
  `dt` text,
  `admin_name` text,
  `ip` text,
  PRIMARY KEY  (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


CREATE TABLE `transaction` (
  `id` int(11) NOT NULL auto_increment,
  `user` text,
  `tname` text,
  `task` text,
  `dt` text,
  `ip` text,
  PRIMARY KEY  (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


CREATE TABLE `unblock_req` (
  `id` int(11) NOT NULL auto_increment,
  `user` text,
  `status` text,
  `req_dt` text,
  `res_dt` text,
  PRIMARY KEY  (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


CREATE TABLE `user` (
  `id` int(11) NOT NULL auto_increment,
  `name` text,
  `pass` text,
  `email` text,
  `mobile` text,
  `addr` text,
  `dob` text,
  `gender` text,
  `pin` text,
  `location` text,
  `image` longblob,
  `status` text,
  PRIMARY KEY  (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


CREATE TABLE `user_web_limits` (
  `id` int(11) NOT NULL auto_increment,
  `user` text,
  `name` text,
  `count` text,
  `type` text,
  PRIMARY KEY  (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


CREATE TABLE `web_limits` (
  `id` int(11) NOT NULL auto_increment,
  `name` text,
  `count` text,
  PRIMARY KEY  (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


